t;span class=&#34;vlist&#34; style=&#34;height:0.2025em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.23em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;frac-line&#34; style=&#34;border-bottom-width:0.04em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.4518em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord accent mtight&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.6679em;&#34;&gt;&lt;span style=&#34;top:-2.7em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;x&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;accent-body&#34; style=&#34;left:-0.2222em;&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;~&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;b&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.3173em;&#34;&gt;&lt;span style=&#34;top:-2.357em;margin-left:0em;margin-right:0.0714em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.5em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size3 size1 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;t&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.2025em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.4868em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose nulldelimiter&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose delimcenter&#34; style=&#34;top:0em;&#34;&gt;&lt;span class=&#34;delimsizing size2&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;激活函数σ表示不同的编码方案，当σ = σ1时，整体行为对应于独热编码，而当σ = σ2时，对应于PLE编码。&lt;/p&gt;
&lt;p&gt;此外，为了在现代深度学习框架中促进加速训练和自动梯度反向传播，给出矩阵行形式&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;bold&#34;&gt;r&lt;/mi&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi&gt;σ&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mrow&gt;&lt;mover accent=&#34;true&#34;&gt;&lt;mi&gt;x&lt;/mi&gt;&lt;mo&gt;~&lt;/mo&gt;&lt;/mover&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mo&gt;∑&lt;/mo&gt;&lt;mover accent=&#34;true&#34;&gt;&lt;mi&gt;α&lt;/mi&gt;&lt;mo&gt;~&lt;/mo&gt;&lt;/mover&gt;&lt;/mrow&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo&gt;∘&lt;/mo&gt;&lt;msup&gt;&lt;mover accent=&#34;true&#34;&gt;&lt;mi&gt;α&lt;/mi&gt;&lt;mo&gt;~&lt;/mo&gt;&lt;/mover&gt;&lt;mrow&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/mrow&gt;&lt;/msup&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mover accent=&#34;true&#34;&gt;&lt;mi&gt;α&lt;/mi&gt;&lt;mo&gt;~&lt;/mo&gt;&lt;/mover&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;softmax&lt;/mi&gt;&lt;mo&gt;⁡&lt;/mo&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;α&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\mathbf{r}=\sigma(({\tilde{x}-\sum\tilde{\alpha}})\circ{\tilde{\alpha}}^{-1}),{\tilde{\alpha}}=\operatorname{softmax}(\alpha)&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.4444em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathbf&#34;&gt;r&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;σ&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;((&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord accent&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.6679em;&#34;&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;x&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.35em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;accent-body&#34; style=&#34;left:-0.2222em;&#34;&gt;&lt;span class=&#34;mord&#34;&gt;~&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mop op-symbol small-op&#34; style=&#34;position:relative;top:0em;&#34;&gt;∑&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord accent&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.6679em;&#34;&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.0037em;&#34;&gt;α&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.35em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;accent-body&#34; style=&#34;left:-0.2222em;&#34;&gt;&lt;span class=&#34;mord&#34;&gt;~&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mbin&#34;&gt;∘&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2222em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.1219em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord accent&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.6679em;&#34;&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.0037em;&#34;&gt;α&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.35em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;accent-body&#34; style=&#34;left:-0.2222em;&#34;&gt;&lt;span class=&#34;mord&#34;&gt;~&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8719em;&#34;&gt;&lt;span style=&#34;top:-3.1208em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord accent&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.6679em;&#34;&gt;&lt;span style=&#34;top:-3em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.0037em;&#34;&gt;α&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.35em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:3em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;accent-body&#34; style=&#34;left:-0.2222em;&#34;&gt;&lt;span class=&#34;mord&#34;&gt;~&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mop&#34;&gt;&lt;span class=&#34;mord mathrm&#34;&gt;softmax&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.0037em;&#34;&gt;α&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;其中◦表示哈达玛积，r ∈ &lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msup&gt;&lt;mi mathvariant=&#34;double-struck&#34;&gt;R&lt;/mi&gt;&lt;mi&gt;T&lt;/mi&gt;&lt;/msup&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\mathbb{R}^{T}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.8413em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathbb&#34;&gt;R&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8413em;&#34;&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.13889em;&#34;&gt;T&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;表示从标量x转换而来的二进制编码向量。L是一个下三角矩阵，对角线以下元素为1&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;B. 关联模式聚合 (Association Pattern Aggregation)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;该模块利用消息传递 GNN 来推导节点与其邻居之间的关联特征。可形式化表示如下&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msubsup&gt;&lt;mi mathvariant=&#34;bold&#34;&gt;h&lt;/mi&gt;&lt;mi&gt;u&lt;/mi&gt;&lt;mi&gt;l&lt;/mi&gt;&lt;/msubsup&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;mrow&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;A&lt;/mi&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;G&lt;/mi&gt;&lt;mi mathvariant=&#34;normal&#34;&gt;G&lt;/mi&gt;&lt;/mrow&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;msubsup&gt;&lt;mi mathvariant=&#34;bold&#34;&gt;h&lt;/mi&gt;&lt;mi&gt;u&lt;/mi&gt;&lt;mrow&gt;&lt;mi&gt;l&lt;/mi&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/mrow&gt;&lt;/msubsup&gt;&lt;mo separator=&#34;true&#34;&gt;,&lt;/mo&gt;&lt;mrow&gt;&lt;msubsup&gt;&lt;mi mathvariant=&#34;bold&#34;&gt;h&lt;/mi&gt;&lt;mi&gt;v&lt;/mi&gt;&lt;mrow&gt;&lt;mi&gt;l&lt;/mi&gt;&lt;mo&gt;−&lt;/mo&gt;&lt;mn&gt;1&lt;/mn&gt;&lt;/mrow&gt;&lt;/msubsup&gt;&lt;mo&gt;∣&lt;/mo&gt;&lt;mi&gt;v&lt;/mi&gt;&lt;mo&gt;∈&lt;/mo&gt;&lt;mi mathvariant=&#34;script&#34;&gt;M&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;(&lt;/mo&gt;&lt;mi&gt;u&lt;/mi&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;mo stretchy=&#34;false&#34;&gt;)&lt;/mo&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;{\bf h}_{u}^{l}=\mathrm{AGG}({\bf h}_{u}^{l-1},{{\bf h}_{v}^{l-1}\mid v\in\mathcal{M}(u)})&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.0961em;vertical-align:-0.247em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathbf&#34;&gt;h&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8491em;&#34;&gt;&lt;span style=&#34;top:-2.453em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;u&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.01968em;&#34;&gt;l&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.247em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.0991em;vertical-align:-0.25em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathrm&#34;&gt;AGG&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathbf&#34;&gt;h&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8491em;&#34;&gt;&lt;span style=&#34;top:-2.453em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;u&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.01968em;&#34;&gt;l&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.247em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mpunct&#34;&gt;,&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.1667em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathbf&#34;&gt;h&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8491em;&#34;&gt;&lt;span style=&#34;top:-2.453em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.03588em;&#34;&gt;v&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.01968em;&#34;&gt;l&lt;/span&gt;&lt;span class=&#34;mbin mtight&#34;&gt;−&lt;/span&gt;&lt;span class=&#34;mord mtight&#34;&gt;1&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.247em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;∣&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;v&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;∈&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathcal&#34;&gt;M&lt;/span&gt;&lt;span class=&#34;mopen&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;u&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mclose&#34;&gt;)&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msubsup&gt;&lt;mi mathvariant=&#34;bold&#34;&gt;h&lt;/mi&gt;&lt;mi&gt;u&lt;/mi&gt;&lt;mi&gt;l&lt;/mi&gt;&lt;/msubsup&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\mathbf{h}_{u}^{l}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.0961em;vertical-align:-0.247em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathbf&#34;&gt;h&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8491em;&#34;&gt;&lt;span style=&#34;top:-2.453em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;u&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34; style=&#34;margin-right:0.01968em;&#34;&gt;l&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.247em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;为节点u在层l的隐藏状态，初始化为&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;msubsup&gt;&lt;mi mathvariant=&#34;bold&#34;&gt;h&lt;/mi&gt;&lt;mi&gt;u&lt;/mi&gt;&lt;mn&gt;0&lt;/mn&gt;&lt;/msubsup&gt;&lt;mo&gt;=&lt;/mo&gt;&lt;msub&gt;&lt;mi&gt;π&lt;/mi&gt;&lt;mi&gt;u&lt;/mi&gt;&lt;/msub&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\mathbf{h}_{u}^{0}=\pi_{u}&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:1.0611em;vertical-align:-0.247em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathbf&#34;&gt;h&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.8141em;&#34;&gt;&lt;span style=&#34;top:-2.453em;margin-left:0em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;u&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;top:-3.063em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;0&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.247em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mrel&#34;&gt;=&lt;/span&gt;&lt;span class=&#34;mspace&#34; style=&#34;margin-right:0.2778em;&#34;&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.5806em;vertical-align:-0.15em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord&#34;&gt;&lt;span class=&#34;mord mathnormal&#34; style=&#34;margin-right:0.03588em;&#34;&gt;π&lt;/span&gt;&lt;span class=&#34;msupsub&#34;&gt;&lt;span class=&#34;vlist-t vlist-t2&#34;&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.1514em;&#34;&gt;&lt;span style=&#34;top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;&#34;&gt;&lt;span class=&#34;pstrut&#34; style=&#34;height:2.7em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;sizing reset-size6 size3 mtight&#34;&gt;&lt;span class=&#34;mord mtight&#34;&gt;&lt;span class=&#34;mord mathnormal mtight&#34;&gt;u&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-s&#34;&gt;​&lt;/span&gt;&lt;/span&gt;&lt;span class=&#34;vlist-r&#34;&gt;&lt;span class=&#34;vlist&#34; style=&#34;height:0.15em;&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;。聚合函数AGG(*)负责将节点u上一层的隐藏状态与其邻居节点的隐藏状态相结合，邻居节点范围由M(u)决定&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;C. 模式全局聚合 (Global Aggregation of Patterns)&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;为了解决欺诈行为在图中的&lt;strong&gt;稀疏性&lt;/strong&gt;和&lt;strong&gt;长程依赖&lt;/strong&gt;问题，该框架引入了全局聚合策略。传统自注意力的主要计算与存储瓶颈在于其O(N2)复杂度。我们观察到，在基于消息传递的空间GNN中，信息聚合后每个步骤的最终层通常只包含少量节点。在每个训练周期中，我们将前一次迭代的GNN输出向量保存为历史嵌入。通过计算这些逐步选择节点与之前整 个周期节点嵌入之间的交叉注意力，可以捕获全局注意力。该方法将O(N2)复杂度降低至O(N · M)，其中M表示批次大小。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;3. 性能表现与实验验证&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;SOTA 性能：&lt;/strong&gt; 在 YelpChi、T-Finance、DGraph 等 7 个真实世界数据集上，GAAP 相较于 24 种基线方法达到了&lt;strong&gt;最先进 (State-of-the-art)&lt;/strong&gt; 的性能。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;业务相关性：&lt;/strong&gt; 实验采用了前 K 个预测中的召回率 (Rec@K) 作为主要指标，这在工业欺诈检测实践中比 AUROC 更具业务相关性。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;消融实验结论：&lt;/strong&gt; 实验证明 DyBEM 对信息密度高的属性提升巨大，而全局聚合模块能显著缓解 GNN 的过度压缩问题。&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;Addition：SOTA**&amp;quot;State-of-the-Art&amp;quot;** 的缩写，在科研和工程领域通常被翻译为“最先进水平”&lt;strong&gt;或&lt;/strong&gt;“当前最优性能”。它代表在特定的任务和数据集上，某一算法或模型表现出的性能已经超越了目前已知的所有其他方法，达到了现有的最高技术水准&lt;/p&gt;
&lt;/blockquote&gt;
&lt;p&gt;复现结果如下所示&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/images/%E8%81%94%E6%83%B3%E6%88%AA%E5%9B%BE_20260617104853.jpg&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/images/%E8%81%94%E6%83%B3%E6%88%AA%E5%9B%BE_20260617105011.jpg&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;p&gt;消融实验由于缺少必要代码，无法进行。&lt;/p&gt;

 &lt;p&gt;The Matrix Cookbook&lt;/p&gt;
&lt;p&gt;Bronstein大神写的《Geometric Deep Learning》&lt;/p&gt;
&lt;p&gt;斯坦福经典《统计学习要素》&lt;/p&gt;
&lt;p&gt;Roman Vershynin 的 High-Dimensional Probability Cover &amp;amp; Thomas的 Elements of Information Theory&lt;/p&gt;

 &lt;h2 id=&#34;gad问题复杂性与挑战&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#gad问题复杂性与挑战&#34;&gt;#&lt;/a&gt; GAD问题复杂性与挑战&lt;/h2&gt;
&lt;h4 id=&#34;主要问题复杂性&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#主要问题复杂性&#34;&gt;#&lt;/a&gt; 主要问题复杂性&lt;/h4&gt;
&lt;h6 id=&#34;来源一图数据本身固有特性&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#来源一图数据本身固有特性&#34;&gt;#&lt;/a&gt; 来源一：图数据本身固有特性&lt;/h6&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;结构依赖性&lt;/strong&gt;：图结构的复杂性体现在不同层次的数据中的连通性模式、依赖关系以及影响程度上，这些因素在判断图中是否存在异常现象时起着至关重要的作用。在独立同分布数据中，异常现象是独立于上下文的，而在图中，&lt;strong&gt;异常现象往往取决于某个图数据实例的上下文&lt;/strong&gt;，比如某个节点的邻近节点。在一个上下文中，某种异常现象可能被视为正常现象，而在另一个上下文中则可能被视为异常现象。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;图类型多样性&lt;/strong&gt;：图的类型很多，各自具有不同的用途和应用场景。根据图是否随时间变化，可以将图分为静态图与动态图两类。此外，还可以根据连接类型将图分为异质连接图与同质连接图。&lt;strong&gt;在一种类型的图中定义异常现象，可能与另一种类型的图有很大差异&lt;/strong&gt;。例如，在动态图中，某个特定时间步骤下明显异常的图实例（如节点/边/图），在观察其演变过程时，可能会表现出较强的规律性；同样地，在同质连接图中，某个图实例的异常表现可能与在异质连接图中截然不同。处理各种类型的图需要 GAD 方法根据图的特性调整其学习策略。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;大规模计算开销&lt;/strong&gt;：现代应用程序需要处理规模巨大的图数据，这些数据可能包含数百万甚至数十亿的节点和边。例如，在大规模社交网络、金融交易网络、网络环境、用户产品电子商务网络以及引用网络等场景中，都需要处理这样的数据。为了利用全局结构信息来识别异常，必须考虑整个图的结构信息，或者至少涉及大部分结构关系。这里的关键难点在于&lt;strong&gt;如何处理加载如此大规模结构关系数据时的时间和空间复杂性问题&lt;/strong&gt;。&lt;/li&gt;
&lt;/ul&gt;
&lt;h6 id=&#34;来源二图异常现象&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#来源二图异常现象&#34;&gt;#&lt;/a&gt; 来源二：图异常现象&lt;/h6&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;多级图异常实例&lt;/strong&gt;：与其他类型的数据异常检测不同，**图数据中的异常可能来自不同的组成部分，比如节点、边、子图，甚至是整个图结构。**取决于图数据的结构和属性信息，图数据中的异常表现形式也多种多样。因此，需要采用综合性的 GAD 方法来识别节点、边、子图以及整个图结构中存在的异常模式。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;多样化的图异常表现形式&lt;/strong&gt;：取决于图的结构信息、属性信息或两者的组合，图异常的表现形式极度多样。如&lt;strong&gt;属性异常&lt;/strong&gt;（在图的属性集中表现出异常特征值的实例）、&lt;strong&gt;结构异常&lt;/strong&gt;（表现出异常连接模式的实例，例如连接了不同的社区或形成了异常密集的连接）、&lt;strong&gt;上下文异常&lt;/strong&gt;（实例本身的属性可能不异常，但与其所属社区的其他节点相比，其属性值存在显著偏差）、&lt;strong&gt;局部亲和力异常&lt;/strong&gt;（与其连接实例表现出极弱亲和力的实例）&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;Addtion：关于&lt;strong&gt;上下文异常&lt;/strong&gt;和&lt;strong&gt;局部亲和力异常&lt;/strong&gt;，我的理解是上下文异常主要是基于图实例所处的社区模式进行判断，而局部亲和力异常主要是基于图实例直接相联的邻居做出判断。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h6 id=&#34;来源三从通用ad继承并在-gad-中被放大的复杂性&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#来源三从通用ad继承并在-gad-中被放大的复杂性&#34;&gt;#&lt;/a&gt; 来源三：从通用AD继承并在 GAD 中被放大的复杂性&lt;/h6&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;异常未知性&lt;/strong&gt;：许多异常在实际发生之前是完全&lt;strong&gt;不可预知&lt;/strong&gt;的。这意味着在建模阶段，研究人员无法获得关于这些异常模式的任何先验知识。由于没有“参考样本”，模型很难提前学习到这些未知异常的特征。此外，在同一个图中，不同类型的异常可能表现出截然不同的行为模式，这种&lt;strong&gt;异质性&lt;/strong&gt;使得检测变得极其困难：如图属性中的异常（如节点特征值极端）与图结构中的异常（如不寻常的连接模式）表现完全不同、节点集的异常行为与边或子图集的异常行为具有不同的特征、在“1阶局部邻域（1-hop local structure）”表现出的异常，与在“高阶结构上下文（higher-order structural context）”中表现出的异常可能完全不相关。由于上述的异质性，&lt;strong&gt;“已知”并不代表“能推导未知”&lt;/strong&gt;。即便模型已经掌握了一种或几种类型的图异常模式，也往往无法泛化（Generalize）到检测其他类型的异常。这直接导致了 GAD 的一个核心挑战：&lt;strong&gt;如何实现对不同图异常的泛化&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;数据不平衡问题&lt;/strong&gt;：由于异常事件在现实中发生频率极低，导致正常类和异常类之间存在巨大的样本量差距。由于图结构或属性的潜在&lt;strong&gt;长尾分布&lt;/strong&gt;特性，这种复杂性在 GAD 中更加明显。具体到模型训练中，由于训练数据中正常实例占据绝对多数，模型在学习过程中会更频繁地接触并感知正常模式，从而产生&lt;strong&gt;偏向多数类的偏见&lt;/strong&gt;。模型可能变得过度“专业化”于识别正常实例，而对异常实例的特征捕捉不足，导致在检测异常时&lt;strong&gt;泛化效果极差&lt;/strong&gt;。许多方法的预测依赖于检测决策阈值，由于数据极度不平衡，&lt;strong&gt;阈值的微小偏差&lt;/strong&gt;都可能导致误报率或漏报率的剧烈波动&lt;/li&gt;
&lt;/ul&gt;
&lt;blockquote&gt;
&lt;p&gt;Addtion：&lt;strong&gt;长尾分布&lt;/strong&gt;，指少数类别或个体（头部）占据了数据中的绝大部分，而大量类别或个体（尾部）虽然各自占比很小，但种类繁多，其总和可能非常可观甚至超过头部。&lt;/p&gt;
&lt;/blockquote&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;异常行为伪装&lt;/strong&gt;：主要指恶意行为者（Bad actors）为了逃避检测，故意调整其特征或连接行为，使其在局部邻域或全局图中看起来与正常实例相似。主要通过两种操纵手段实现：
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;属性操纵（Attribute Manipulation）：&lt;/strong&gt; 修改自身的特征属性，使其在特征空间中接近正常节点的分布。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;结构操纵（Structural Manipulation）：&lt;/strong&gt; 故意与大量正常节点建立连接。即异常节点有很大可能连接到正常节点，从而掩盖其自身的异常本质&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h4 id=&#34;主要挑战&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#主要挑战&#34;&gt;#&lt;/a&gt; 主要挑战&lt;/h4&gt;
&lt;p&gt;上述问题的复杂性导致了在 GAD 领域存在许多尚未解决的挑战，而深入的 GAD 方法可以在一定程度上解决这些挑战。&lt;/p&gt;
&lt;h6 id=&#34;挑战一结构感知与过平滑平衡&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#挑战一结构感知与过平滑平衡&#34;&gt;#&lt;/a&gt; 挑战一：结构感知与过平滑平衡&lt;/h6&gt;
&lt;p&gt;图异常的出现并非仅仅由它们的属性决定，还受到其结构环境的影响。因此，GAD 方法需要在异常评分函数中有效&lt;strong&gt;捕捉这些结构上的依赖性&lt;/strong&gt;。此外，在建模图结构信息时，由于对邻近节点的表示进行迭代聚合来获得目标节点的表示，导致不同节点的表示变得过于相似，会产生**过平滑，**使得正常和异常图实例之间难以区分&lt;/p&gt;
&lt;blockquote&gt;
&lt;p&gt;Addtion：为什么会产生过平滑？GNN 的核心是通过多层特征聚合（Feature Aggregation）来学习节点表示。在每一层中，目标节点都会收集并整合其邻居节点的信息。随着聚合次数（即模型层数）的增加，每个节点所包含的信息不再仅仅局限于其直接邻居，而是扩展到了更远距离的节点。这意味着在多轮迭代后，图中**很大一部分节点的特征信息都会被相互传播和混合。**当这种聚合不断重复时，原本具有独特属性或结构特征的节点，其表示会逐渐趋向于邻域甚至全图的平均水平。最终，&lt;strong&gt;不同节点的表示会变得过度相似&lt;/strong&gt;，从而失去了区分度&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h6 id=&#34;挑战二大规模图结构分析能力&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#挑战二大规模图结构分析能力&#34;&gt;#&lt;/a&gt; 挑战二：大规模图结构分析能力&lt;/h6&gt;
&lt;h6 id=&#34;挑战三对不同类型图异常情况的泛化处理&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#挑战三对不同类型图异常情况的泛化处理&#34;&gt;#&lt;/a&gt; 挑战三：对不同类型图异常情况的泛化处理&lt;/h6&gt;
&lt;p&gt;由于存在&lt;strong&gt;多级图异常实例&lt;/strong&gt;与&lt;strong&gt;多样化的图异常表现形式&lt;/strong&gt;，因此很难采用一刀切的方法来处理这些异常，需要结合强大的特征提取能力和多样化的检测模型。&lt;/p&gt;
&lt;h6 id=&#34;挑战四平衡型-gad&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#挑战四平衡型-gad&#34;&gt;#&lt;/a&gt; 挑战四：平衡型 GAD&lt;/h6&gt;
&lt;p&gt;由于存在&lt;strong&gt;数据不平衡问题&lt;/strong&gt;，因而挑战在于避免产生偏见的全局异常检测结果。&lt;/p&gt;
&lt;h6 id=&#34;挑战五鲁棒性与结果可解释性&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#挑战五鲁棒性与结果可解释性&#34;&gt;#&lt;/a&gt; 挑战五：鲁棒性与结果可解释性&lt;/h6&gt;
&lt;p&gt;鲁棒性是指模型在面对不利条件时维持检测性能的能力，主要涉及以下两个方面：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;对抗异常伪装 (Abnormality Camouflage)：&lt;/strong&gt; 恶意行为者会通过操纵属性或结构（例如故意连接大量正常节点），使异常实例在局部邻域或全局图中看起来与正常实例无异。模型必须具备捕捉这些细微差异的能力，防止异常节点的表示被正常邻域“同化”。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;应对异常污染 (Anomaly Contamination)：&lt;/strong&gt; 现有的无监督方法通常在包含异常的“污染”数据上训练。这些异常实例会干扰 GNN 的消息传递过程，导致学到的表示偏离正常的统计分布。目前的应对策略包括使用截断图数据训练或利用少量已知的正常样本进行半监督学习。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;可解释性是指模型不仅要能检测出异常，还要解释_为什么_该实例被判定为异常。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;应用需求：&lt;/strong&gt; 在银行欺诈检测等关键领域，解释至关重要。调查人员需要知道欺诈行为具体关联到了哪些交易属性、哪些节点间的关系以及发生在哪个时间段。&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;gad技术分类体系&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#gad技术分类体系&#34;&gt;#&lt;/a&gt; GAD技术分类体系&lt;/h2&gt;
&lt;p&gt;该综述提出了深度 GAD 分类体系的总体框架，从三个宏观层面和 13 个细粒度技术角度进行了划分。如下图所示&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/images/%E8%81%94%E6%83%B3%E6%88%AA%E5%9B%BE_20260614100154.jpg&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;h4 id=&#34;gnn框架设计&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#gnn框架设计&#34;&gt;#&lt;/a&gt; GNN框架设计&lt;/h4&gt;
&lt;p&gt;专注于改进图神经网络（GNN）以学习更具判别力的表示&lt;/p&gt;
&lt;h6 id=&#34;判别式gnn模型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#判别式gnn模型&#34;&gt;#&lt;/a&gt; 判别式GNN模型&lt;/h6&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;聚合机制&lt;/strong&gt;：一个基本原则是设计适合图异常实例的特征聚合（FAG）方案。这一类GAD方法假设图中来自同一类的连接实例具有相似的特征，从中我们可以进行特征聚合，以获得具有判别性的正常/异常模式。一种广泛使用的FAG机制如下&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;{h}_{i}^{(l)}=\sigma\left(W^{(l)}\left({h}_{i}^{(l-1)}+{AGG}\left(\left{{h}_{j}^{(l-1)}\mid o_{j}\in{N}_{i}\right}\right)\right)\right)&lt;/p&gt;
&lt;pre&gt;&lt;code&gt;- 其中$\mathrm{h}_{i}^{(l)}$是实例i在第l层的特征表示，$\sigma$是激活函数，${\bf W}^{(l)}$是第l层的训练参数。图实例$o_{i}$通常被设置为节点$v_{i}$，而$N_{i}$通常是节点$v_{i}$的1跳邻域。AGG(·)通过求和或平均聚合来实现，即对邻域特征表示进行求和或平均。更高级的聚合方法，如基于注意力的聚合和LSTM，也被广泛使用 。为了对抗异常行为伪装，应对过平滑问题，产生了以下三种方案
- **硬边选择 (Hard Edge Selection)：** 旨在直接剪枝或过滤掉那些可能导致误导的异质边
- **软边选择 (Soft Edge Selection)：** 与硬性的剪枝不同，软选择利用注意力机制为边分配权重
- **边合成 (Edge Synthesis)：**与侧重于过滤局部结构的边选择不同，**边合成 (Ψ)** 旨在通过构建新的连接来捕获更广泛的全局模式，补充局部信息的不足
&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;特征变换&lt;/strong&gt;：&lt;strong&gt;从原始属性或 GNN 学习到的表示中提取最具判别性的信号，并丢弃无关信息&lt;/strong&gt;
&lt;ul&gt;
&lt;li&gt;**梯度评分(Gradient-based Feature Scoring)：**核心思想是利用监督信号的反馈来识别哪些特征对区分正常和异常实例贡献最大。核心思想是利用监督信号的反馈来识别哪些特征对区分正常和异常实例贡献最大&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;谱过滤器(Spectral Graph Filter)：&lt;strong&gt;谱过滤器结合了谱图理论与 GNN，通过在拉普拉斯矩阵的特征空间中操作来提取复杂的结构属性。其核心假设为&lt;/strong&gt;正常节点&lt;/strong&gt;通常与其邻居具有相似特征，表现为&lt;strong&gt;低频信号&lt;/strong&gt;；而&lt;strong&gt;异常节点&lt;/strong&gt;往往由于偏离常规模式而表现出与周围环境的不一致性，即&lt;strong&gt;高频信号&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h6 id=&#34;生成式gnn模型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#生成式gnn模型&#34;&gt;#&lt;/a&gt; 生成式GNN模型&lt;/h6&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;特征插值：&lt;strong&gt;是应对图异常检测中数据极度不平衡和异常多样性的一项关键技术,。生成式 GNN 的核心逻辑是通过合成伪异常（Pseudo-anomalies）来扩充训练数据，为模型提供更丰富的监督信号。借鉴了传统机器学习中的&lt;/strong&gt;过采样&lt;/strong&gt;思想，其基本操作是通过现有实例表示的凸组合来生成新的图实例表示。该技术假设在异常类实例之间进行插值得到的特征表示，能够很好地与异常类的实际分布对齐&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;噪声扰动&lt;/strong&gt;：&lt;strong&gt;先验驱动的随机噪声&lt;/strong&gt;（如高斯分布）来生成新的图实例，从而模拟异常的统计分布或结构特征&lt;/li&gt;
&lt;/ul&gt;

 &lt;p&gt;Git不会自动走代理，假如git推不上可以查下代理端口然后&lt;/p&gt;
&lt;p&gt;git config --global http.proxy &lt;a href=&#34;http://127.0.0.1&#34;&gt;http://127.0.0.1&lt;/a&gt;:端口号&lt;/p&gt;
&lt;p&gt;git config --global https.proxy &lt;a href=&#34;http://127.0.0.1&#34;&gt;http://127.0.0.1&lt;/a&gt;:端口号&lt;/p&gt;
&lt;p&gt;配置一下&lt;/p&gt;

 &lt;p&gt;学术界管理参考文献的标准格式，是 TeX/LaTeX 系统的配套工具。它把一篇论文的信息（标题、作者、会议、年份等）存成结构化文本，方便引用。Google Scholar中，每篇论文的 &amp;quot;Cite&amp;quot; 按钮弹出的就是 BibTeX。DBLP中，每篇论文旁边的 [bib] 链接就是 BibTeX。&lt;/p&gt;
&lt;p&gt;基本语法结构：&lt;/p&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-plain&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span&gt;@类型 {引用键,&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;  字段名1 = {字段值1},&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;  字段名2 = &#34;字段值2&#34;,&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;  ...&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span&gt;}&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;ul&gt;
&lt;li&gt;@类型：定义文献种类（如 article, book, inproceedings）&lt;/li&gt;
&lt;li&gt;‌引用键 (Citation Key)：唯一标识符。你在 LaTeX 中使用 \cite{引用键} 时就是用它。建议命名规范：作者姓氏 + 年份 + 关键词 (例如：wangtao2026GAD)。&lt;/li&gt;
&lt;li&gt;‌字段：描述文献的元数据（作者、标题、期刊等）。&lt;/li&gt;
&lt;li&gt;‌分隔符：字段值可以用 {} 或 &amp;quot;&amp;quot; 包裹。
&lt;ul&gt;
&lt;li&gt;推荐 {}：因为它能更好地处理包含引号、大括号或特殊字符的内容（如化学式 H2OH2​O 或带重音的字母）。&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;常见条目类型：&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;/images/%E5%9B%BE%E7%89%87.png&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;

 &lt;h2 id=&#34;顶会-顶刊&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#顶会-顶刊&#34;&gt;#&lt;/a&gt; &lt;a href=&#34;https://blog.csdn.net/Edward1027/article/details/145945409&#34;&gt;顶会、顶刊&lt;/a&gt;&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;WWW会议&lt;/strong&gt;（The International Conference of World Wide Web）：CCF A类会议，Core Conference Ranking A*类会议。几乎计算机的任何一个领域都可以投WWW&lt;/p&gt;
&lt;p&gt;WWW每年的录取率非常低，在15年之前甚至是低于15%，15年之后开始在15%-20%之间波动，但是近两年有抬头的趋势，例如21年的录取率甚至打破了20%的红线，为20.6%！不过22年开始回落，估计是会议方要严控质量。投稿量有中跳跃提升的感觉，近三年已经稳定超过1000篇了，2022年同样达到历史最高值，1783篇！由于录取率非常低，所以WWW每年录用的文章相对不高，近三年才超过200篇，2021年达到峰值357篇，今年为341篇&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;AAAI会议&lt;/strong&gt;（AAAI（Association for the Advancement of Artificial Intelligence）Conference on Artificial Intelligence）：CCF A类会议，CAAI A类会议。涵盖人工智能的各个方面。&lt;/p&gt;
&lt;p&gt;据说review比较random。据说是ai顶会里最水的一批，但比IJCAI和MM强&lt;/p&gt;
&lt;p&gt;以 2026 年会议为例，收到投稿超 2.3 万篇，录用率约为 17.6%。‌‌2025年录用率约为 23.4%，投稿量约 1.3 万篇。2024年录用率约为 23.75%，投稿量约 9862 篇&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;KDD会议&lt;/strong&gt;（ACM SIGKDD Conference on Knowledge Discovery and Data Minin）：CCF A类会议。涵盖数据挖掘、机器学习、大数据分析、人工智能应用等方向的‌&lt;strong&gt;研究（Research Track）与应用（Applied Data Science Track）并重&lt;/strong&gt;‌的综合性顶会。&lt;/p&gt;
&lt;p&gt;据说审稿周期长，没有rebuttal，录取率还控制的比较低。publicity/accessibility做得不够好。相比之下cvpr的文章经常能搜到介绍网站，代码也比较清晰。acl/emnlp/naacl的所有文章都能在anthology里找到。kdd现在开完了，好多文章根本找不到。&lt;/p&gt;
&lt;p&gt;录用率2026年为18.5%，2025年约18.7%，2024年约20%&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;ICLR会议&lt;/strong&gt; (International Conference on Learning Representations) ：CCF A类会议。是机器学习领域的顶级会议之一，专注于深度学习、表示学习、生成模型、强化学习等相关主题。ICLR首次举办于2013年，近年来已经成为与 NeurIPS 和 ICML 并列的三大机器学习会议之一。&lt;/p&gt;
&lt;p&gt;毫无疑问的高含金量，过程为全程open review ，所有reviewer的意见都可以看到，同时每一个人都可以随意点评和给分&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;ICLR 2026&lt;/strong&gt;‌：约 ‌**28%**‌（投稿~19,000 篇）&lt;/li&gt;
&lt;li&gt;‌&lt;strong&gt;ICLR 2025&lt;/strong&gt;‌：约 ‌**32.08%**‌（投稿~11,565 篇）&lt;/li&gt;
&lt;li&gt;‌&lt;strong&gt;ICLR 2024&lt;/strong&gt;‌：约 ‌**31%**‌（投稿~7,262 篇）&lt;/li&gt;
&lt;li&gt;‌&lt;strong&gt;ICLR 2023&lt;/strong&gt;‌：约 ‌**31.8%**‌（投稿~5,000 篇）‌‌&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;ICML会议&lt;/strong&gt;（International Conference on Machine Learning，国际机器学习会议）：CCF A类会议。涵盖机器学习各个方面的研究。ICML的内容涉及的主题更加广泛，包括统计学习、生成模型、强化学习等多个领域。ICLR则专注于深度学习的最新进展，因此它在深度学习领域的影响力相较于ICML会更强。&lt;/p&gt;
&lt;p&gt;和ICLR一样毫无疑问的高含金量。想发paper光靠调参在模型上提点不够，还需要能够在数学上解释为什么能有效果，两个会议都相当注重数学理论基础。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;ICML 2026&lt;/strong&gt;‌：23,918 投稿 → ‌**6,352 录用（26.6%）**‌&lt;/li&gt;
&lt;li&gt;‌&lt;strong&gt;ICML 2025&lt;/strong&gt;‌：约 12,107 投稿 → ‌**3,260 录用（~26.9%）**‌&lt;/li&gt;
&lt;li&gt;‌&lt;strong&gt;ICML 2024&lt;/strong&gt;‌：9,473 投稿 → ‌**2,609 录用（27.5%）**‌&lt;/li&gt;
&lt;li&gt;‌&lt;strong&gt;ICML 2023&lt;/strong&gt;‌：6,538 投稿 → ‌&lt;strong&gt;1,827 录用（27.9%）&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;TKDE期刊&lt;/strong&gt;（IEEE Transactions on Knowledge and Data Engineering）：CCF A类期刊，中科院1区TOP。专注于计算机科学、人工智能、电气工程、计算机工程和其他适当领域的知识和数据工程方面。&lt;strong&gt;最新影响因子达 10.4&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;该刊实行三重评审制度，录用率长期低于15%，投稿至录用的平均周期为8-14个月，部分复杂稿件甚至需16个月。&lt;/p&gt;

 &lt;p&gt;已知线性回归假设标签y可以表示为特征x的加权和，即&lt;/p&gt;
&lt;p&gt;&lt;code&gt;y=wx+b&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;但是实际情况下，真实的y和通过这个线性模型由x推导出的y&#39;之间往往存在着差值。我们可以将这个差值&lt;span class=&#34;katex&#34;&gt;&lt;span class=&#34;katex-mathml&#34;&gt;&lt;math xmlns=&#34;http://www.w3.org/1998/Math/MathML&#34;&gt;&lt;semantics&gt;&lt;mrow&gt;&lt;mi&gt;ϵ&lt;/mi&gt;&lt;/mrow&gt;&lt;annotation encoding=&#34;application/x-tex&#34;&gt;\epsilon&lt;/annotation&gt;&lt;/semantics&gt;&lt;/math&gt;&lt;/span&gt;&lt;span class=&#34;katex-html&#34; aria-hidden=&#34;true&#34;&gt;&lt;span class=&#34;base&#34;&gt;&lt;span class=&#34;strut&#34; style=&#34;height:0.4306em;&#34;&gt;&lt;/span&gt;&lt;span class=&#34;mord mathnormal&#34;&gt;ϵ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; 视为一个符合正态分布 &lt;code&gt;N(0，$\epsilon^{2}$ )&lt;/code&gt;的噪声，即真实标签可以表示为&lt;/p&gt;
&lt;p&gt;&lt;code&gt;$y=wx+b+\epsilon，\epsilon\sim\mathcal{N}(0,\sigma^{2})$&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;已知x的情况下，&lt;code&gt;$y-\mathbf{w}^{\textsf{T}}\mathbf{x}-b$&lt;/code&gt;的取值即为&lt;code&gt;$\epsilon$&lt;/code&gt;的概率密度函数，即&lt;/p&gt;
&lt;p&gt;&lt;code&gt;$P(\epsilon)=P(y\mid\mathbf{x})={\frac{1}{\sqrt{2\pi\sigma^{2}}}}\mathrm{exp}\left(-{\frac{1}{2\sigma^{2}}}(y-\mathbf{w}^{\textsf{T}}\mathbf{x}-b)^{2}\right).$&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;由极大似然估计法，可知参数w和b的最优值是使整个数据集的似然最大的值：&lt;/p&gt;
&lt;p&gt;&lt;code&gt;$P({\bf y}\mid{\bf x})=\prod_{i=1}^{n}p(y^{(i)}|{\bf x}^{(i)}).$&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;通过负对数化简化极大似然估计量，将问题简化为使极大似然估计量的负对数取得最小值：&lt;/p&gt;
&lt;p&gt;&lt;code&gt;$-\log P(y\mid\mathbf{X})=\sum_{i=1}^{n}{\frac{1}{2}}\log(2\pi\sigma^{2})+{\frac{1}{2\sigma^{2}}}\Big(y^{(i)}-\mathbf{w}^{\mathsf{T}}\mathbf{x}^{(i)}-b\Big)^{2}.$&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;假设&lt;code&gt;$\sigma$&lt;/code&gt;为固定常数，则可忽略第一项，而第二项即为均方误差的线性变换。&lt;/p&gt;
&lt;p&gt;因而得证均方误差最小化等价于令整个数据集的&lt;code&gt;$P({\bf y}\mid{\bf x})$&lt;/code&gt;最大化&lt;/p&gt;

 &lt;h2 id=&#34;引言&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#引言&#34;&gt;#&lt;/a&gt; 引言&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;benchmark&lt;/strong&gt;（基准）的原意是用作衡量、比较或判断其他事物性能、质量、价值等的参照点或标准。相比普通论文，benchmark论文并不发明新的方法，而是把别人已经提出的方法全部拉出来，在统一的条件（相同数据、相同评价标准、相同硬件）下公平比拼，回答一个问题：&amp;quot;到底谁更强？&amp;quot;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;GAD&lt;/strong&gt;(图异常检测)是一种识别图中那些与大多数参考对象存在显著偏离的异常图对象的过程，这些对象可以包括&lt;strong&gt;节点&lt;/strong&gt;、&lt;strong&gt;边&lt;/strong&gt;或&lt;strong&gt;子结构&lt;/strong&gt;等。其应用领域包括：防止金融欺诈和洗钱行为、预测网络入侵和设备故障、识别垃圾评论和虚假新闻等。相比表格数据异常检测，GAD将对象间的依赖关系纳入考虑，增强了识别欺诈行为的能力，但与此同时也存在着&lt;strong&gt;标签不平衡&lt;/strong&gt;、&lt;strong&gt;特征多样性&lt;/strong&gt;以及&lt;strong&gt;关系伪装&lt;/strong&gt;等独特的挑战。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;标签不平衡：异常对象远少于正常对象（10000个人中只有1个骗子）&lt;/li&gt;
&lt;li&gt;特征异配：&lt;a href=&#34;https://blog.csdn.net/weixin_51087794/article/details/144307689&#34;&gt;同配图和异配图是什么&lt;/a&gt; 异常节点和邻居节点通常特征差异更大，呈现出高异配性：异常节点更倾向于和特征、标签不同的正常节点相连，和正常节点普遍存在的同配性（同类特征节点相连）形成鲜明对比，这种特征异质性会干扰GNN的邻居聚合过程，增加异常检测难度。&lt;/li&gt;
&lt;li&gt;关系伪装：异常节点会主动和大量正常节点建立连接，伪装成正常样本的关系结构，降低自身被识别的概率；但实际上异常节点仍主要和同类异常节点保持核心连接，这种连接模式提升了检测难度（骗子会故意加大量正常人为好友躲避检测）&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;下图为目前的GAD基准&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;https://raw.githubusercontent.com/chenlan7064/Picbed_PicGo/main/img/GAD%E5%9F%BA%E5%87%86.jpg&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;p&gt;从图中可以看到，目前GAD基准存在的问题：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;缺乏一个全面的监督性（半监督+有监督）基准。与此同时，已经存在非常多时间序列数据、图像、视频以及表格数据的异常检测基准&lt;/li&gt;
&lt;li&gt;树集成方法与GNN之间的比较缺乏研究。前面的基准只对GNN方法进行了比较，最新的BOND基准依然只包括GNN和标准方法&lt;/li&gt;
&lt;li&gt;对大尺度图的探索依然有限。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;GADbench&lt;/strong&gt;所做的，就是在&lt;strong&gt;GAD&lt;/strong&gt;(图异常检测)领域提供了一个针对静态图的有监督方法基准。&lt;/p&gt;
&lt;h2 id=&#34;gadbench构成&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#gadbench构成&#34;&gt;#&lt;/a&gt; GADbench构成&lt;/h2&gt;
&lt;h4 id=&#34;基准数据集&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基准数据集&#34;&gt;#&lt;/a&gt; 基准数据集&lt;/h4&gt;
&lt;p&gt;来自真实世界的10个GAD数据集&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;https://raw.githubusercontent.com/chenlan7064/Picbed_PicGo/main/img/%E5%9F%BA%E5%87%86%E6%95%B0%E6%8D%AE%E9%9B%86.jpg&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;p&gt;可以看到，这些数据集具有以下特点：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;真实的异常&lt;/strong&gt;：GADBench 中的数据集仅包含在实际场景中自然出现的异常情况，这与之前那些使用合成异常数据进行 GAD 评估的研究有所不同。这些早期的研究通常会向正常图结构中插入人工节点属性和结构，比如 Cora[71]中的做法，从而生成一些相对容易识别的异常，而且这些异常显然与现实世界中的异常有所不同。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;广泛的领域&lt;/strong&gt;：GADBench 中的数据集涵盖多个领域，包括社交媒体、电子商务、电子金融以及众包等&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;不同的规模范围&lt;/strong&gt;：GADBench 的数据集涵盖了广泛的节点数量范围，从数千（weibo,8405）到数百万(T-social,5781065)个节点不等&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;不平衡的比例&lt;/strong&gt;：每个数据集中的异常数量超过 100 个，这样可以保证实验结果的稳定性：同时，异常比例不超过 25%，从而保留了 GAD 系统固有的不平衡特性。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;在这些数据集中，Weibo、Reddit、Questions 和 T-Social 这些数据集被专门用于识别社交媒体平台上的异常账户。Tolokers、Amazon 和 YelpChi 数据集则旨在检测众包或电子商务平台上的欺诈性员工、评论以及评论者。T-Finance、Elliptic 和 DGraph-Fin 这些数据集则分别专注于识别金融网络中的欺诈用户、非法实体以及逾期未偿还的贷款。如需了解每个数据集的更详细描述&lt;/p&gt;
&lt;h4 id=&#34;基准模型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基准模型&#34;&gt;#&lt;/a&gt; 基准模型&lt;/h4&gt;
&lt;h6 id=&#34;经典方法&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#经典方法&#34;&gt;#&lt;/a&gt; 经典方法&lt;/h6&gt;
&lt;p&gt;MLP, KNN, SVM, RF, XGBoost, XGBOD, NA&lt;/p&gt;
&lt;h6 id=&#34;标准gnn&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#标准gnn&#34;&gt;#&lt;/a&gt; 标准GNN&lt;/h6&gt;
&lt;p&gt;GCN , SGC , GIN , GraphSAGE , GAT , GT , PNA ,BGNN, RGCN , HGT&lt;/p&gt;
&lt;h6 id=&#34;异常检测特化的gnn&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#异常检测特化的gnn&#34;&gt;#&lt;/a&gt; 异常检测特化的GNN&lt;/h6&gt;
&lt;p&gt;GAS , DCI , PC-GNN , GAT-sep , BernNet , AMNet ,BWGNN , GHRN , CARE-GNN , H2-FDetector&lt;/p&gt;
&lt;h6 id=&#34;基于邻居聚合的树集成模型&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基于邻居聚合的树集成模型&#34;&gt;#&lt;/a&gt; 基于邻居聚合的树集成模型&lt;/h6&gt;
&lt;p&gt;RF-Graph，XGB-Graph&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;https://raw.githubusercontent.com/chenlan7064/Picbed_PicGo/main/img/%E5%9F%BA%E5%87%86%E6%A8%A1%E5%9E%8B.jpg&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;h4 id=&#34;评估指标&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#评估指标&#34;&gt;#&lt;/a&gt; 评估指标&lt;/h4&gt;
&lt;p&gt;AUROC：ROC曲线下的面积，对头部的预测不敏感&lt;/p&gt;
&lt;p&gt;AUPRC：PR曲线下的面积，适配GAD中正负样本（异常样本极少）极度不平衡的场景，在ROC和top-k之间取得了平衡&lt;/p&gt;
&lt;p&gt;Rec@K：基于top-K检索的召回率指标，对整体不敏感&lt;/p&gt;
&lt;h2 id=&#34;复现&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#复现&#34;&gt;#&lt;/a&gt; 复现&lt;/h2&gt;
&lt;h4 id=&#34;默认超参数条件全监督&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#默认超参数条件全监督&#34;&gt;#&lt;/a&gt; 默认超参数条件+全监督&lt;/h4&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;https://raw.githubusercontent.com/chenlan7064/Picbed_PicGo/main/img/fig_Rec%40K_barchart.png&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;https://raw.githubusercontent.com/chenlan7064/Picbed_PicGo/main/img/fig_AUROC_barchart.png&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;https://raw.githubusercontent.com/chenlan7064/Picbed_PicGo/main/img/fig_AUPRC_barchart.png&#34; alt=&#34;&#34; /&gt;&lt;img loading=&#34;lazy&#34; src=&#34;https://raw.githubusercontent.com/chenlan7064/Picbed_PicGo/main/img/AUPRC_boxplot.png&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;https://raw.githubusercontent.com/chenlan7064/Picbed_PicGo/main/img/Rec%40K_boxplot.png&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;https://raw.githubusercontent.com/chenlan7064/Picbed_PicGo/main/img/AUROC_boxplot.png&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;p&gt;&lt;img loading=&#34;lazy&#34; src=&#34;https://raw.githubusercontent.com/chenlan7064/Picbed_PicGo/main/img/Time_Total.png&#34; alt=&#34;&#34; /&gt;&lt;/p&gt;
&lt;p&gt;结果分析：在所有模型使用默认超参数，全监督的情况下，采用邻居聚合机制的集成树具有显著优越的性能，XGB-Graph 和 RF-Graph 在所有指标上都持续优于其他比较模型&lt;/p&gt;
&lt;h4 id=&#34;实验中遇到的问题&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#实验中遇到的问题&#34;&gt;#&lt;/a&gt; 实验中遇到的问题&lt;/h4&gt;
&lt;p&gt;一开始我是打算在本地跑这个实验的，但是本地是5070显卡，论文环境依赖的DGL 官方没有为 Windows 发布 CUDA 12.4+ 版本，而 RTX 5070 又必须用 CUDA 12.4+才支持。两个约束冲突了。我尝试通过WSL来规避这个问题，但依然困难重重，最终还是决定转云平台&lt;/p&gt;
&lt;p&gt;由于论文实验环境是48GB显存，而云平台4090是24GB显存，因而在 tfinance上跑HGT时炸显存了，HGT跳过。&lt;/p&gt;
&lt;p&gt;DGraph-Fin和T-Social数据集过于庞大，超出承受范围，同样予以跳过。&lt;/p&gt;

 &lt;h3 id=&#34;文献翻译&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#文献翻译&#34;&gt;#&lt;/a&gt; 文献翻译&lt;/h3&gt;
&lt;p&gt;&lt;a href=&#34;https://github.com/AaronGIG/pdf2zh-desktop&#34;&gt;pdf2zh项目&lt;/a&gt;（开箱即用版）&lt;/p&gt;
&lt;h3 id=&#34;网盘&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#网盘&#34;&gt;#&lt;/a&gt; 网盘&lt;/h3&gt;
&lt;p&gt;MEGA云盘：无广告，上传下载不限速，外网下行带宽2Mbps左右，内网下行带宽100Mbps左右。下载一个文件的平均速度在30Mbps以上，不限制上传文件大小、类型，注重隐私安全性&lt;/p&gt;
&lt;h3 id=&#34;日程管理&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#日程管理&#34;&gt;#&lt;/a&gt; 日程管理&lt;/h3&gt;
&lt;p&gt;Outlook：windows自带&lt;/p&gt;
&lt;h3 id=&#34;浏览器插件&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#浏览器插件&#34;&gt;#&lt;/a&gt; 浏览器插件&lt;/h3&gt;
&lt;p&gt;&lt;a href=&#34;https://immersivetranslate.com/&#34;&gt;沉浸式翻译&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&#34;https://www.doubao.com/browser-extension/landing&#34;&gt;豆包，浏览器 AI 助手&lt;/a&gt;&lt;/p&gt;
&lt;p&gt;&lt;a href=&#34;https://chromewebstore.google.com/detail/tampermonkey/dhdgffkkebhmkfjojejmpbldmpobfkfo?pli=1&#34;&gt;篡改猴&lt;/a&gt;&lt;/p&gt;
&lt;h3 id=&#34;科学上网&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#科学上网&#34;&gt;#&lt;/a&gt; 科学上网&lt;/h3&gt;
&lt;p&gt;扬帆云&lt;/p&gt;
&lt;h3 id=&#34;git管理&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#git管理&#34;&gt;#&lt;/a&gt; Git管理&lt;/h3&gt;
&lt;p&gt;fork：可视化Git管理工具&lt;/p&gt;
&lt;h3 id=&#34;绘图工具&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#绘图工具&#34;&gt;#&lt;/a&gt; 绘图工具&lt;/h3&gt;
&lt;p&gt;&lt;a href=&#34;https://plus.excalidraw.com/&#34;&gt;Excalidraw&lt;/a&gt;：在线白板，可以便捷绘制示例图形&lt;/p&gt;
&lt;p&gt;&lt;a href=&#34;https://alexlenail.me/NN-SVG/index.html&#34;&gt;NN SVG&lt;/a&gt;：神经网络绘制&lt;/p&gt;
&lt;h3 id=&#34;latex公式编辑&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#latex公式编辑&#34;&gt;#&lt;/a&gt; Latex公式编辑&lt;/h3&gt;
&lt;p&gt;&lt;a href=&#34;https://mathcheap.xyz/&#34;&gt;&lt;s&gt;mathcheap&lt;/s&gt;&lt;/a&gt;&lt;s&gt;：OCR识别生成Latex公式，美中不足的是没有提供模板来自行组装公式&lt;/s&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;首选：&lt;/strong&gt;&lt;a href=&#34;https://github.com/lukas-blecher/latex-ocr&#34;&gt;latex-ocr项目&lt;/a&gt;：支持图形化界面操作，提供Latex公式OCR识别&lt;/p&gt;
&lt;p&gt;&lt;a href=&#34;https://www.latexlive.com/##&#34;&gt;latexlive&lt;/a&gt;：提供了可以自行组装公式的模板&lt;/p&gt;
&lt;h3 id=&#34;agent&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#agent&#34;&gt;#&lt;/a&gt; Agent&lt;/h3&gt;
&lt;p&gt;claude：非常好用，专注于代码和命令行操作&lt;/p&gt;

 &lt;h2 id=&#34;张量&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#张量&#34;&gt;#&lt;/a&gt; 张量&lt;/h2&gt;
&lt;h4 id=&#34;张量初始化&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#张量初始化&#34;&gt;#&lt;/a&gt; 张量初始化&lt;/h4&gt;
&lt;p&gt;通用可选参数:&lt;/p&gt;
&lt;p&gt;&lt;code&gt;dtype&lt;/code&gt;：指定数据类型，比如 &lt;code&gt;torch.float32&lt;/code&gt; 或 &lt;code&gt;torch.int64&lt;/code&gt;，不填就自动猜。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;device&lt;/code&gt;：指定存在GPU还是CPU&lt;/p&gt;
&lt;p&gt;&lt;code&gt;requires_grad&lt;/code&gt;：设为 &lt;code&gt;True&lt;/code&gt; 就能让张量跟踪梯度，用于模型训练，默认是 &lt;code&gt;False&lt;/code&gt;。&lt;/p&gt;
&lt;h6 id=&#34;从数据直接创建&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#从数据直接创建&#34;&gt;#&lt;/a&gt; 从数据直接创建&lt;/h6&gt;
&lt;p&gt;&lt;code&gt;torch.tensor(data)&lt;/code&gt;:直接从给定数据data创建张量。&lt;/p&gt;
&lt;h6 id=&#34;创建具有特定填充值的张量&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#创建具有特定填充值的张量&#34;&gt;#&lt;/a&gt; 创建具有特定填充值的张量&lt;/h6&gt;
&lt;p&gt;&lt;code&gt;torch.zeros(size)&lt;/code&gt;：创建一个值全为零，shape为&lt;code&gt;size&lt;/code&gt;的张量。&lt;code&gt;size&lt;/code&gt;可为元组或直接输入shape&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;典型用途：初始化偏置项、创建占位符。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;code&gt;torch.ones(size)&lt;/code&gt;：创建一个值全为一的张量。 同上&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;典型用途：初始化归一化层、创建全一掩码。&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;code&gt;torch.full(size, fill_value)&lt;/code&gt;：创建指定形状、元素全部填充为给定值 &lt;code&gt;fill_value&lt;/code&gt; 的张量。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;torch.zeros_like(input)/torch.ones_like(input)/torch.full_like(input, fill_value)&lt;/code&gt;：创建一个shape与&lt;code&gt;input&lt;/code&gt;张量相同，值全为0/1/fill_value的张量&lt;/p&gt;
&lt;h6 id=&#34;创建随机初始化张量&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#创建随机初始化张量&#34;&gt;#&lt;/a&gt; 创建随机初始化张量&lt;/h6&gt;
&lt;p&gt;&lt;code&gt;torch.randn(size)&lt;/code&gt;：创建一个遵循标准正态分布的张量。 权重初始化的常用选择&lt;/p&gt;
&lt;p&gt;&lt;code&gt;torch.normal(mean, std, size, generator=None, out=None)&lt;/code&gt;：创建一个遵循标准正态分布的张量。&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;mean&lt;/code&gt;：指定均值&lt;/li&gt;
&lt;li&gt;&lt;code&gt;std&lt;/code&gt;：指定标准差&lt;/li&gt;
&lt;li&gt;&lt;code&gt;size&lt;/code&gt;：指定输出张量的形状&lt;/li&gt;
&lt;li&gt;&lt;code&gt;generator&lt;/code&gt;：指定随机数生成器，用于复现采样结果&lt;/li&gt;
&lt;li&gt;&lt;code&gt;out&lt;/code&gt;：指定输出张量，避免重复开辟内存&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;code&gt;torch.rand(size)&lt;/code&gt;：创建一个遵循01均匀分布的张量。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;torch.randint(low，high，size)&lt;/code&gt;：在区间 [&lt;code&gt;low&lt;/code&gt;, &lt;code&gt;high&lt;/code&gt;) 内生成随机整数，形成指定形状的张量。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;torch.empty(size)&lt;/code&gt;：分配指定形状的未初始化内存。其值取决于当时内存状态，是随机的。通常不直接用于初始化参数，而是作为某些操作的中间步骤。&lt;/p&gt;
&lt;h6 id=&#34;创建序列张量&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#创建序列张量&#34;&gt;#&lt;/a&gt; 创建序列张量&lt;/h6&gt;
&lt;p&gt;&lt;code&gt;torch.arange(*start=0，end，*step=1)&lt;/code&gt;：创建一个从 &lt;code&gt;start&lt;/code&gt; 到 &lt;code&gt;end&lt;/code&gt;（不包括&lt;code&gt;end&lt;/code&gt;），步长为 &lt;code&gt;step&lt;/code&gt; 的一维序列张量。&lt;/p&gt;
&lt;p&gt;&lt;code&gt;torch.linspace(start，end，step)&lt;/code&gt;：创建一个在[&lt;code&gt;start&lt;/code&gt;，&lt;code&gt;end&lt;/code&gt;]**(特例，一般是左闭右开)**上等距生成&lt;code&gt;step&lt;/code&gt;个点的一维张量&lt;/p&gt;
&lt;h6 id=&#34;创建特殊矩阵&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#创建特殊矩阵&#34;&gt;#&lt;/a&gt; 创建特殊矩阵&lt;/h6&gt;
&lt;p&gt;&lt;code&gt;torch.eye(n)&lt;/code&gt;：创建 &lt;strong&gt;n × n&lt;/strong&gt; 的&lt;strong&gt;单位矩阵&lt;/strong&gt;（主对角线为1，其余为0）。&lt;/p&gt;
&lt;h6 id=&#34;从外部库numpy创建张量&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#从外部库numpy创建张量&#34;&gt;#&lt;/a&gt; 从外部库（Numpy）创建张量&lt;/h6&gt;
&lt;p&gt;&lt;code&gt;torch.from_numpy(ndarray)&lt;/code&gt;：从 NumPy 数组 &lt;code&gt;ndarray&lt;/code&gt; 创建张量。&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;关键点&lt;/strong&gt;：返回的张量与 NumPy 数组&lt;strong&gt;共享底层内存&lt;/strong&gt;，修改一个会影响另一个。&lt;/p&gt;
&lt;h4 id=&#34;张量属性&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#张量属性&#34;&gt;#&lt;/a&gt; 张量属性&lt;/h4&gt;
&lt;p&gt;注：以*指代执行以下方法的张量&lt;/p&gt;
&lt;h6 id=&#34;基础属性&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#基础属性&#34;&gt;#&lt;/a&gt; 基础属性&lt;/h6&gt;
&lt;p&gt;&lt;code&gt;*.shape/*.size()&lt;/code&gt;：张量形状&lt;/p&gt;
&lt;p&gt;&lt;code&gt;*.dtype&lt;/code&gt;：张量中每个元素的数据类型&lt;/p&gt;
&lt;p&gt;&lt;code&gt;*.device&lt;/code&gt;：张量所处计算设备（CPU/GPU某张卡）&lt;/p&gt;
&lt;p&gt;&lt;code&gt;*.nidm/*.dim()&lt;/code&gt;：张量的秩（shape元组的长度）&lt;/p&gt;
&lt;p&gt;&lt;code&gt;*.numel()&lt;/code&gt;：返回张量中所有元素的总个数，即 &lt;code&gt;shape&lt;/code&gt; 中各维度大小的乘积&lt;/p&gt;
&lt;p&gt;&lt;code&gt;len(*)&lt;/code&gt;：返回张量第0维的长度&lt;/p&gt;
&lt;h6 id=&#34;计算图相关属性&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#计算图相关属性&#34;&gt;#&lt;/a&gt; 计算图相关属性&lt;/h6&gt;
&lt;p&gt;&lt;code&gt;*.requires_grad&lt;/code&gt;：指示是否对该张量进行梯度跟踪，通常在创建张量时指定，默认为&lt;code&gt;False&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;*.grad&lt;/code&gt;：存储张量的梯度。在调用 &lt;code&gt;backward()&lt;/code&gt; 进行反向传播后，如果该张量的 &lt;code&gt;requires_grad&lt;/code&gt; 为 &lt;code&gt;True&lt;/code&gt;，且是计算图中的叶节点，其计算出的梯度将存储在此属性中。在反向传播之前为 &lt;code&gt;None&lt;/code&gt;&lt;/p&gt;
&lt;p&gt;&lt;code&gt;*.is_leaf&lt;/code&gt;：指示该张量是否为计算图中的叶节点。叶节点通常指由用户直接创建（而非通过其他张量运算得到）且 &lt;code&gt;requires_grad=True&lt;/code&gt; 的张量。叶节点的梯度在反向传播后会被保留。&lt;/p&gt;
&lt;h4 id=&#34;张量操作&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#张量操作&#34;&gt;#&lt;/a&gt; 张量操作&lt;/h4&gt;
&lt;p&gt;&lt;code&gt;*.reshape(shape)&lt;/code&gt;：张量形状变为&lt;code&gt;shape&lt;/code&gt;，&lt;code&gt;shape&lt;/code&gt;的某个特征维度可为-1，pytorch框架会自动计算该维度大小。&lt;/p&gt;
&lt;h2 id=&#34;采样&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#采样&#34;&gt;#&lt;/a&gt; 采样&lt;/h2&gt;
&lt;p&gt;&lt;code&gt;multinomial.Multinomial(total_count, probs=None, logits=None)&lt;/code&gt;：&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;code&gt;total_count&lt;/code&gt;为整数，单次实验中总共进行的独立试验次数&lt;/li&gt;
&lt;li&gt;&lt;code&gt;probs&lt;/code&gt;为形状为&lt;code&gt;[k]&lt;/code&gt;的张量，表示k个互斥事件各自发生的概率，要求所有元素和为1，支持未归一化的权重，会自动转换为概率&lt;/li&gt;
&lt;li&gt;&lt;code&gt;logits&lt;/code&gt;和&lt;code&gt;probs&lt;/code&gt;二选一，是概率的对数形式，适合数值不稳定场景下使用&lt;/li&gt;
&lt;/ul&gt;

 &lt;hr /&gt;
&lt;h2 id=&#34;1-流程图-flowchart&#34;&gt;&lt;a class=&#34;anchor&#34; href=&#34;#1-流程图-flowchart&#34;&gt;#&lt;/a&gt; 1. 流程图 (Flowchart)&lt;/h2&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-mermaid&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;graph LR&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;    A&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;[&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;开始&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;]&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; --&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;&gt;&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; B&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;{&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;判断条件&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;}&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;    B --&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;&gt;&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;|是| C&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;[&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;执行 A&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;]&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;    B --&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;&gt;&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;|否| D&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;[&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;执行 B&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;]&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;    C --&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;&gt;&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; E&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;[&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;结束&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;]&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;    D --&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;&gt;&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; E&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;
&lt;pre class=&#34;shiki shiki-themes vitesse-light vitesse-dark&#34; style=&#34;background-color:#ffffff;--shiki-dark-bg:#121212;color:#393a34;--shiki-dark:#dbd7caee&#34; tabindex=&#34;0&#34;&gt;&lt;code class=&#34;language-mermaid&#34;&gt;&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;graph TB&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;    subgraph 前端&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;        A&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;[&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;用户请求&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;]&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; --&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;&gt;&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt; B&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;[&lt;/span&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;负载均衡&lt;/span&gt;&lt;span style=&#34;color:#2993a3;--shiki-dark:#5eaab5&#34;&gt;]&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;    end&lt;/span&gt;&lt;/span&gt;
&lt;span class=&#34;line&#34;&gt;&lt;span style=&#34;color:#393A34;--shiki-dark:#DBD7CAEE&#34;&gt;    subgraph 后端&lt;/span&gt;&lt;/span&gt;
